package com.example.community.service.impl;
import com.example.community.entity.UserConcern;import com.example.community.mapper.UserConcernMapper;import com.example.community.service.ConcernService;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;
@Service @RequiredArgsConstructor public class ConcernServiceImpl implements ConcernService {private final UserConcernMapper mapper;public List<UserConcern> followers(Integer id){return mapper.selectList(new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<UserConcern>().eq(UserConcern::getLastuser,id));}public List<UserConcern> following(Integer id){return mapper.selectList(new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<UserConcern>().eq(UserConcern::getPreuser,id));}public boolean status(Integer pre,Integer last){return mapper.selectCount(query(pre,last))>0;}@Transactional public UserConcern follow(UserConcern v){if(v.getPreuser().equals(v.getLastuser()))throw new IllegalArgumentException("不能关注自己");if(status(v.getPreuser(),v.getLastuser()))throw new IllegalArgumentException("已经关注该用户");mapper.insert(v);return v;}@Transactional public void unfollow(Integer pre,Integer last){if(mapper.delete(query(pre,last))==0)throw new IllegalArgumentException("关注关系不存在");}private com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<UserConcern> query(Integer pre,Integer last){return new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<UserConcern>().eq(UserConcern::getPreuser,pre).eq(UserConcern::getLastuser,last);}}
